      {
        mp[pair<int, int>(v.x , v.y)] = true;
        ans ++;
      }

      int lev = v.lev;
      int far = v.far;

      int x2 = v.x , y2 = v.y;

      if(lev == n + 1)
        continue;

      if(far != t[lev])
      {
        x2 += dx[v.dir] , y2 += dy[v.dir];
        if(marked[x2][y2][v.dir][lev][far + 1]) continue;
        marked[x2][y2][v.dir][lev][far + 1] = true;
        Q.push(node(x2 , y2 , v.dir , lev , far + 1));
      }
      else
      {
        pair<int, int> dirs = rot(v.dir);
        if(!marked[v.x][v.y][dirs.first][lev + 1][0])
        {
            marked[v.x][v.y][dirs.first][lev + 1][0] = true;
            Q.push(node(v.x, v.y , dirs.first, lev + 1, 0));
        }
        if(!marked[v.x][v.y][dirs.second][lev + 1][0])
        {
            marked[v.x][v.y][dirs.second][lev + 1][0] = true;
            Q.push(node(v.x, v.y , dirs.second, lev + 1, 0));
        }
      }
  }
  cout << ans << endl;

  return 0;
}
